#define JPEG_QUANT_TABLE_LEN    32

static const uint32_t jpeg_quant_table[JPEG_QUANT_TABLE_LEN] = {
	0x07060608, 0x07080506, 0x09090707, 0x140c0a08,
	0x0b0b0c0d, 0x1312190c, 0x1a1d140f, 0x1a1d1e1f,
