		jpeg_ll_disable_yuv_mode(hal->hw);
		jpeg_ll_enable_jpeg_mode(hal->hw);
	}

	return BK_OK;
}

bk_err_t jpeg_hal_stop_common(jpeg_hal_t *hal, yuv_mode_t mode)
