static int bk7258_gc2145_stop_capture(FAR struct imgsensor_s *sensor,
                                       imgsensor_stream_type_t type)
{
  FAR struct bk7258_gc2145_dev_s *priv =
      (FAR struct bk7258_gc2145_dev_s *)sensor;

  /* Close the DVP pads, so the next session can arm the encoder against a
   * quiescent bus (bk7258_gc2145_set_stream()).
   *
   * v4l2_cap.c's complete_capture() reaches stop_capture() from interrupt
   * context when it runs out of vacant buffer containers, and the I2C here is
   * a bitbang that must not run there -- nor may this printf().  In that case
   * the write is deferred to the next start_capture(), which closes the pads
   * before it programs anything.  The frame that session starts on is then
   * recovered by the capture module's VSYNC handler, exactly as it was before
   * this gate existed.
   */

  if (up_interrupt_context())
    {
      priv->stream_off_pending = true;
      return OK;
    }

  bk7258_gc2145_set_stream(priv, false);
  return OK;
}

